import React from "react"
import { graphql, useStaticQuery, withPrefix } from "gatsby"

const toAbsoluteUrl = (value, siteUrl) => {
  if (!value) return undefined
  if (/^(data:|https?:|mailto:)/i.test(value)) return value

  try {
    return new URL(withSitePrefix(value), `${siteUrl}/`).toString()
  } catch {
    return value
  }
}

const normalizePath = (pathname) => {
  if (!pathname) return "/"
  const path = pathname.startsWith("/") ? pathname : `/${pathname}`
  return path.replace(/\/+$/, "") || "/"
}

const withSitePrefix = (pathname) => {
  const prefix = withPrefix("/").replace(/\/+$/, "")
  const path = normalizePath(pathname)

  return path === prefix || path.startsWith(`${prefix}/`)
    ? path
    : withPrefix(path)
}

const Seo = ({
  title,
  description,
  date,
  image,
  imageAlt,
  imageWidth,
  imageHeight,
  what = "website",
  tags,
  schemaMarkup,
  pathname = "/",
  price,
  currency,
}) => {
  const { site } = useStaticQuery(graphql`
    query SiteSeoMetadata {
      site {
        siteMetadata {
          siteUrl
          title
          image
          imageWidth
          imageHeight
          description
          author
        }
      }
    }
  `)

  const metadata = site.siteMetadata
  const siteUrl = (metadata.siteUrl || "").replace(/\/+$/, "")
  const siteName = metadata.title || "Wisdel.uk"
  const pagePath = normalizePath(pathname)
  const canonicalUrl = new URL(withSitePrefix(pagePath), `${siteUrl}/`).toString()
  const pageTitle = title || siteName
  const pageDescription = description || metadata.description
  const pageImage = toAbsoluteUrl(image || metadata.image, siteUrl)
  const type = ["article", "product", "profile"].includes(what) ? what : "website"
  const fullTitle = pageTitle === siteName ? pageTitle : `${pageTitle} | ${siteName}`

  return (
    <>
      <html lang="en-GB" />
      <title>{fullTitle}</title>
      {pageDescription && <meta name="description" content={pageDescription} />}
      <meta name="robots" content="index, follow" />
      <link rel="canonical" href={canonicalUrl} />

      {schemaMarkup && (
        <script type="application/ld+json">
          {JSON.stringify(schemaMarkup)}
        </script>
      )}

      <meta property="og:url" content={canonicalUrl} />
      <meta property="og:type" content={type} />
      <meta property="og:site_name" content={siteName} />
      <meta property="og:title" content={fullTitle} />
      <meta property="og:description" content={pageDescription} />
      <meta property="og:locale" content="en_GB" />
      {pageImage && <meta property="og:image" content={pageImage} />}
      {imageAlt && <meta property="og:image:alt" content={imageAlt} />}
      {(imageWidth || metadata.imageWidth) && (
        <meta property="og:image:width" content={String(imageWidth || metadata.imageWidth)} />
      )}
      {(imageHeight || metadata.imageHeight) && (
        <meta property="og:image:height" content={String(imageHeight || metadata.imageHeight)} />
      )}

      <meta name="twitter:card" content="summary_large_image" />
      <meta name="twitter:title" content={fullTitle} />
      <meta name="twitter:description" content={pageDescription} />
      <meta name="twitter:url" content={canonicalUrl} />
      {pageImage && <meta name="twitter:image" content={pageImage} />}
      {imageAlt && <meta name="twitter:image:alt" content={imageAlt} />}

      {type === "article" && date && (
        <meta property="article:published_time" content={date} />
      )}
      {type === "article" && metadata.author && (
        <meta property="article:author" content={metadata.author} />
      )}
      {type === "article" && tags &&
        tags.split(/[\s,]+/).filter(Boolean).map((tag, index) => (
          <meta property="article:tag" key={`${tag}-${index}`} content={tag} />
        ))}

      {type === "profile" && (
        <>
          <meta property="profile:first_name" content="Christian" />
          <meta property="profile:last_name" content="Lacdael" />
        </>
      )}

      {type === "product" && price != null && (
        <meta property="product:price:amount" content={String(price)} />
      )}
      {type === "product" && currency && (
        <meta property="product:price:currency" content={currency} />
      )}
    </>
  )
}

export default Seo
